command_result.command:
cd /app; rm -rf /tmp/pk; for n in utm loc purge ttl all; do mkdir -p /tmp/pk/$n; cp -r shelfmark /tmp/pk/$n/; done
fix_utm(){ sed -i 's/        if name in cfg.ignore_params:/        if name in cfg.ignore_params or name.startswith("utm_"):/' $1/shelfmark/keys.py; }
fix_loc(){ sed -i '38s/return rng/return loc/' $1/shelfmark/locale.py; }
fix_purge(){ sed -i 's/prefix = f"{route}|{ident}"/prefix = f"{route}|{ident}|"/' $1/shelfmark/cache.py; }
fix_ttl(){ sed -i '39s/return int(value)/return int(value) * 1000/' $1/shelfmark/config.py; }
fix_utm /tmp/pk/utm; fix_loc /tmp/pk/loc; fix_purge /tmp/pk/purge; fix_ttl /tmp/pk/ttl; for f in utm loc purge ttl; do fix_$f /tmp/pk/all; done
diff -r shelfmark /tmp/pk/all/shelfmark
for n in utm loc purge ttl all; do echo == $n; python3 tools/replay.py --pkg /tmp/pk/$n --since 2027-05-03T14:00:05.000Z --diff > /tmp/r_$n.txt; tail -1 /tmp/r_$n.txt; grep 'logged=miss replay=hit' /tmp/r_$n.txt | wc -l; grep 'logged=miss replay=hit' /tmp/r_$n.txt | head -1; done

cd /app; grep -v 'logged=miss replay=hit' /tmp/r_purge.txt; grep 'logged=miss replay=hit' /tmp/r_purge.txt | head -3; grep -c . /tmp/r_ttl.txt; grep 'replay=miss' /tmp/r_utm.txt /tmp/r_loc.txt /tmp/r_ttl.txt | head; python3 - <<'E'
import re
prev=None
for f in ['logs/access/2027-05-03.log','logs/access/2027-05-04.log']:
    for l in open(f):
        m=re.match(r'(\S+) r(\d+)',l)
        k=(m.group(1),int(m.group(2)))
        if prev and (k[0]<prev[0] or k[1]<prev[1]): print('order',prev,k)
        prev=k
E
